# Structured logging setup
class SecurityLogger:
    def __init__(self, splunk_url: str = None, elastic_url: str = None):
        self.logger = logging.getLogger("ZeroTrustPlaybook")
        self.logger.setLevel(logging.INFO)

        # Console handler
        console_handler = logging.StreamHandler(sys.stdout)
        console_format = logging.Formatter(
            '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        console_handler.setFormatter(console_format)
        self.logger.addHandler(console_handler)

        # Centralized logging endpoints
        self.splunk_url = splunk_url
        self.elastic_url = elastic_url

    def log_structured(self, level: str, event: Dict, error_details: Dict = None):
        """Send structured logs to centralized platforms"""
        log_entry = {
            "timestamp": datetime.utcnow().isoformat(),
            "playbook_version": "2.0",
            "event": event,
            "error_details": error_details
        }

        # Log locally
        if level == "error":
            self.logger.error(json.dumps(log_entry))
        elif level == "warning":
            self.logger.warning(json.dumps(log_entry))
        else:
            self.logger.info(json.dumps(log_entry))

        # Send to Splunk (HTTP Event Collector)
        if self.splunk_url:
            try:
                splunk_payload = {
                    "event": log_entry,
                    "sourcetype": "soar:playbook",
                    "source": "zero_trust_containment"
                }
                requests.post(self.splunk_url, json=splunk_payload, timeout=5)
            except Exception as e:
                self.logger.error(f"Failed to send to Splunk: {e}")

        # Send to Elasticsearch
        if self.elastic_url:
            try:
                elastic_payload = {
                    "@timestamp": datetime.utcnow().isoformat(),
                    "message": log_entry
                }
                requests.post(self.elastic_url, json=elastic_payload, timeout=5)
            except Exception as e:
                self.logger.error(f"Failed to send to Elasticsearch: {e}")

    def capture_error(self, context: str, exception: Exception, 
                     incident_id: str = None, **kwargs):
        """Capture detailed error information"""
        error_details = {
            "context": context,
            "exception_type": type(exception).__name__,
            "exception_message": str(exception),
            "traceback": traceback.format_exc(),
            "incident_id": incident_id,
            "additional_context": kwargs
        }

        self.log_structured("error", 
                           {"action": "error", "context": context},
                           error_details)
        return error_details
