class CloudNativeOrchestrator:
    def __init__(self, k8s_config: Dict = None, aws_config: Dict = None):
        self.k8s_config = k8s_config
        self.aws_config = aws_config

    def get_pod_details(self, pod_name: str, namespace: str = "default") -> Dict:
        """Get Kubernetes pod details"""
        if not self.k8s_config:
            return {}

        try:
            # Using Kubernetes Python client
            from kubernetes import client, config

            if self.k8s_config.get("in_cluster"):
                config.load_incluster_config()
            else:
                config.load_kube_config()

            v1 = client.CoreV1Api()
            pod = v1.read_namespaced_pod(pod_name, namespace)

            return {
                "ip": pod.status.pod_ip,
                "node_ip": pod.status.host_ip,
                "labels": pod.metadata.labels,
                "namespace": pod.metadata.namespace,
                "is_container": True
            }

        except Exception as e:
            raise Exception(f"Failed to get pod details: {e}")

    def isolate_kubernetes_pod(self, pod_name: str, namespace: str) -> Dict:
        """Isolate a Kubernetes pod using network policies"""
        try:
            from kubernetes import client, config

            if self.k8s_config.get("in_cluster"):
                config.load_incluster_config()
            else:
                config.load_kube_config()

            # Create a NetworkPolicy that denies all ingress/egress
            network_policy = client.V1NetworkPolicy(
                metadata=client.V1ObjectMeta(
                    name=f"quarantine-{pod_name}",
                    namespace=namespace
                ),
                spec=client.V1NetworkPolicySpec(
                    pod_selector=client.V1LabelSelector(
                        match_labels={"pod-name": pod_name}
                    ),
                    policy_types=["Ingress", "Egress"],
                    ingress=[],  # No ingress allowed
                    egress=[]    # No egress allowed
                )
            )

            netv1 = client.NetworkingV1Api()
            netv1.create_namespaced_network_policy(namespace, network_policy)

            return {"success": True, "policy_name": f"quarantine-{pod_name}"}

        except Exception as e:
            raise Exception(f"Failed to isolate Kubernetes pod: {e}")

    def get_lambda_function_details(self, function_name: str) -> Dict:
        """Get AWS Lambda function details"""
        if not self.aws_config:
            return {}

        try:
            import boto3
            lambda_client = boto3.client(
                'lambda',
                aws_access_key_id=self.aws_config.get('access_key'),
                aws_secret_access_key=self.aws_config.get('secret_key'),
                region_name=self.aws_config.get('region', 'us-east-1')
            )

            response = lambda_client.get_function(FunctionName=function_name)

            return {
                "function_name": response['Configuration']['FunctionName'],
                "runtime": response['Configuration']['Runtime'],
                "last_modified": response['Configuration']['LastModified'],
                "is_serverless": True,
                "vpc_config": response['Configuration'].get('VpcConfig', {})
            }

        except Exception as e:
