class ThreatIntelligenceEngine:
    def __init__(self, ti_providers: Dict):
        self.providers = ti_providers  # {"virustotal": {"api_key": ""}, "alienvault": {}}
        self.cache = {}
        self.cache_ttl = timedelta(minutes=30)

    def enrich_iocs(self, iocs: List[str]) -> Dict:
        """Enrich IOCs with multiple threat intelligence sources"""
        enriched_results = {}

        for ioc in iocs:
            cached_result = self._get_cached_result(ioc)
            if cached_result:
                enriched_results[ioc] = cached_result
                continue

            ioc_results = {}

            # Query VirusTotal
            if "virustotal" in self.providers:
                vt_result = self._query_virustotal(ioc)
                ioc_results["virustotal"] = vt_result

            # Query AlienVault OTX
            if "alienvault" in self.providers:
                otx_result = self._query_alienvault(ioc)
                ioc_results["alienvault"] = otx_result

            # Query internal threat intel
            internal_result = self._query_internal_threat_intel(ioc)
            ioc_results["internal"] = internal_result

            # Calculate overall score
            ioc_results["overall_confidence"] = self._calculate_confidence(ioc_results)
            ioc_results["last_updated"] = datetime.utcnow().isoformat()

            # Cache result
            self._cache_result(ioc, ioc_results)
            enriched_results[ioc] = ioc_results

        return enriched_results

    def _query_virustotal(self, ioc: str) -> Dict:
        """Query VirusTotal API"""
        api_key = self.providers["virustotal"]["api_key"]

        # Determine IOC type
        if "." in ioc and "/" not in ioc:  # Likely domain
            url = f"https://www.virustotal.com/api/v3/domains/{ioc}"
        elif len(ioc) == 64:  # SHA256
            url = f"https://www.virustotal.com/api/v3/files/{ioc}"
        else:  # IP address
            url = f"https://www.virustotal.com/api/v3/ip_addresses/{ioc}"

        headers = {"x-apikey": api_key}

        try:
            response = requests.get(url, headers=headers, timeout=10)
            if response.status_code == 200:
                data = response.json()
                attributes = data.get("data", {}).get("attributes", {})

                return {
                    "malicious_votes": attributes.get("last_analysis_stats", {}).get("malicious", 0),
                    "suspicious_votes": attributes.get("last_analysis_stats", {}).get("suspicious", 0),
                    "total_votes": sum(attributes.get("last_analysis_stats", {}).values()),
                    "reputation": attributes.get("reputation", 0),
                    "tags": attributes.get("tags", [])
                }
        except Exception as e:
            pass

        return {"error": "query_failed"}

    def get_recommended_actions(self, enriched_iocs: Dict) -> List[str]:
        """Generate recommended actions based on threat intelligence"""
        actions = []
        confidence_threshold = 0.7

        for ioc, data in enriched_iocs.items():
            confidence = data.get("overall_confidence", 0)

            if confidence > confidence_threshold:
                if data.get("virustotal", {}).get("malicious_votes", 0) > 5:
                    actions.append("immediate_containment")
                    actions.append("network_block_ioc")

                if "ransomware" in data.get("tags", []):
                    actions.append("enable_backup_protection")
                    actions.append("alert_security_team")

                if data.get("internal", {}).get("previously_seen", False):
                    actions.append("apply_known_remediation")

        return list(set(actions))  # Remove duplicates
