            # 4. Execute containment based on target type
            containment_results = self._execute_targeted_containment(
                target_details, 
                policy_decision
            )

            # 5. Add to monitoring system
            if containment_results.get("success"):
                self.monitor.add_monitored_host({
                    **target_details,
                    "containment_time": datetime.utcnow().isoformat(),
                    "policy_applied": policy_decision
                })

            # 6. Return comprehensive results
            return {
                "success": True,
                "incident_id": enriched_incident.get("incident_id"),
                "policy_decision": policy_decision,
                "target_details": target_details,
