        result = orjson.loads(data)

        # Additional validation
        self._validate_deserialized_data(result)
        return result

    def _validate_deserialized_data(self, data: Dict):
        """Validate deserialized data against schema"""
        # Validate incident_id format
        if not re.match(r'^INC-\d{4}-\d{3,}$', data.get('incident_id', '')):
            raise ValueError("Invalid incident_id format")

        # Validate timestamp
        try:
            datetime.fromisoformat(data.get('timestamp', '').replace('Z', '+00:00'))
        except ValueError:
            raise ValueError("Invalid timestamp format")

        # Validate IP addresses if present
        if 'host_ip' in data:
            if not self._is_valid_ip(data['host_ip']):
                raise ValueError(f"Invalid IP address: {data['host_ip']}")

    @staticmethod
    def _is_valid_ip(ip: str) -> bool:
        """Validate IP address format"""
        ipv4_pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
        ipv6_pattern = r'^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$'
        return bool(re.match(ipv4_pattern, ip) or re.match(ipv6_pattern, ip))

class EncryptedSerializer(SecureSerializer):
    """Serializer with encryption for sensitive data"""

    def __init__(self, encryption_key: bytes = None):
        if encryption_key is None:
            # Generate key if not provided (store securely in production!)
            encryption_key = Fernet.generate_key()
        self.cipher = Fernet(encryption_key)
        self.json_serializer = SecureJSONSerializer()

    def serialize(self, data: Dict) -> bytes:
        # First serialize to JSON
        json_data = self.json_serializer.serialize(data)
        # Then encrypt
        return self.cipher.encrypt(json_data)

    def deserialize(self, data: bytes) -> Dict:
        # Decrypt first
        decrypted = self.cipher.decrypt(data)
        # Then deserialize JSON
        return self.json_serializer.deserialize(decrypted)

class SecureHTTPClient:
    """Secure HTTP client with timeout, retries, and SSL verification"""

    def __init__(self, timeout: int = 30, max_retries: int = 3):
        self.timeout = timeout
        self.max_retries = max_retries
        self.session = self._create_secure_session()

    def _create_secure_session(self):
        """Create a secure requests session"""
        import requests
        from requests.adapters import HTTPAdapter
        from urllib3.util.retry import Retry

        session = requests.Session()

        # Configure SSL/TLS
        session.verify = True  # Always verify SSL certificates
        session.cert = None    # Client certificate if needed

        # Configure TLS settings
        try:
            import urllib3
            urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
        except:
            pass

        # Configure retry strategy
        retry_strategy = Retry(
            total=self.max_retries,
            backoff_factor=1,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=["HEAD", "GET", "POST", "PUT", "DELETE", "OPTIONS", "TRACE"]
        )

        adapter = HTTPAdapter(max_retries=retry_strategy)
        session.mount("http://", adapter)
        session.mount("https://", adapter)

        return session

    def request(self, method: str, url: str, **kwargs) -> requests.Response:
        """Make secure HTTP request"""
        # Validate URL
        parsed = urlparse(url)
        if parsed.scheme not in ['http', 'https']:
            raise ValueError(f"Invalid URL scheme: {parsed.scheme}")

        # Ensure timeout is set
        kwargs.setdefault('timeout', self.timeout)

        # Add security headers
        headers = kwargs.get('headers', {})
        headers.update({
            'User-Agent': 'ZeroTrustPlaybook/3.0',
            'X-Content-Type-Options': 'nosniff',
            'X-Frame-Options': 'DENY',
        })
        kwargs['headers'] = headers

        try:
            response = self.session.request(method, url, **kwargs)
            response.raise_for_status()
            return response
        except requests.exceptions.RequestException as e:
            # Log without exposing sensitive info
            logging.error(f"HTTP request failed for {method} {url}: {type(e).__name__}")
            raise

class SecureConfigManager:
    """Secure configuration management with secrets handling"""

    def __init__(self, use_vault: bool = False):
        self.use_vault = use_vault
        self.secrets = {}

        # In production, use HashiCorp Vault, AWS Secrets Manager, or Azure Key Vault
        if use_vault:
            self._init_vault_client()

    def _init_vault_client(self):
        """Initialize HashiCorp Vault client"""
        try:
            import hvac
            # Configuration should come from environment variables
            vault_url = os.environ.get('VAULT_ADDR')
            vault_token = os.environ.get('VAULT_TOKEN')

            if vault_url and vault_token:
                self.vault_client = hvac.Client(url=vault_url, token=vault_token)
            else:
                logging.warning("Vault credentials not found in environment")
                self.vault_client = None
        except ImportError:
            logging.warning("hvac not installed, falling back to env vars")
            self.vault_client = None

    def get_secret(self, secret_name: str) -> str:
        """Get secret from secure storage"""
        if self.use_vault and self.vault_client:
            try:
                secret = self.vault_client.secrets.kv.v2.read_secret_version(
                    path=secret_name
                )
                return secret['data']['data']['value']
            except Exception as e:
                logging.error(f"Failed to get secret from Vault: {e}")

        # Fallback to environment variables (less secure)
        env_var = f"ZT_{secret_name.upper()}"
        secret = os.environ.get(env_var)

        if not secret:
            raise ValueError(f"Secret {secret_name} not found in environment")

        return secret

    def validate_api_key(self, key: str, service: str) -> bool:
        """Validate API key format"""
        patterns = {
            'crowdstrike': r'^[a-f0-9]{32}$',
            'virustotal': r'^[a-f0-9]{64}$',
            'generic': r'^[A-Za-z0-9\-_]{20,}$'
        }

        pattern = patterns.get(service, patterns['generic'])
        return bool(re.match(pattern, key))

class InputValidator:
    """Comprehensive input validation"""

    @staticmethod
    def validate_host_identifier(identifier: str) -> bool:
        """Validate host identifier (IP, hostname, or UUID)"""
        # Check if it's a valid IP
        if SecureJSONSerializer._is_valid_ip(identifier):
            return True

        # Check if it's a valid hostname
        if re.match(r'^[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?)*$', identifier):
            return True

        # Check if it's a UUID
        if re.match(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', identifier, re.I):
            return True

        return False

    @staticmethod
    def sanitize_string(input_str: str, max_length: int = 255) -> str:
        """Sanitize string input"""
        if not input_str:
            return ""

        # Remove null bytes
        sanitized = input_str.replace('\x00', '')

        # Truncate to max length
        if len(sanitized) > max_length:
            sanitized = sanitized[:max_length]

        # Remove potentially dangerous characters
        sanitized = re.sub(r'[<>"\'&;]', '', sanitized)

        return sanitized.strip()

    @staticmethod
    def validate_incident_data(data: Dict) -> Dict:
        """Validate and sanitize incident data"""
        validated = {}

        # Required fields
        required = ['incident_id', 'timestamp', 'action']
        for field in required:
            if field not in data:
                raise ValueError(f"Missing required field: {field}")

        # Sanitize string fields
        string_fields = ['incident_id', 'action', 'description', 'resource_name']
        for field in string_fields:
            if field in data:
                validated[field] = InputValidator.sanitize_string(str(data[field]))

        # Validate specific formats
        if 'host_ip' in data:
            if not SecureJSONSerializer._is_valid_ip(data['host_ip']):
                raise ValueError(f"Invalid IP: {data['host_ip']}")
            validated['host_ip'] = data['host_ip']

        # Validate severity
        if 'severity' in data:
            severity = data['severity'].lower()
            if severity not in ['low', 'medium', 'high', 'critical']:
                raise ValueError(f"Invalid severity: {severity}")
            validated['severity'] = severity

        return validated

class RateLimiter:
    """Rate limiting to prevent abuse"""

    def __init__(self, max_requests: int = 100, window_seconds: int = 60):
        self.max_requests = max_requests
        self.window = timedelta(seconds=window_seconds)
        self.requests = {}

    def check_limit(self, client_id: str) -> bool:
        """Check if client has exceeded rate limit"""
        now = datetime.utcnow()

        if client_id not in self.requests:
            self.requests[client_id] = []

        # Remove old requests
        self.requests[client_id] = [
            req_time for req_time in self.requests[client_id]
            if now - req_time < self.window
        ]

        # Check limit
        if len(self.requests[client_id]) >= self.max_requests:
            return False

        # Add current request
        self.requests[client_id].append(now)
        return True

